        public static string PrintFeatures(bool isReachable, double distance, double nnConfWeight, double angleWeight, double euclidDist, double nnConfSqrDiff, bool areBothRoadEnds, double avgColorDiff, double avgPathColor)
        {
            double awd = angleWeight / distance;
            double cwd = nnConfWeight / distance;
            double distanceEuclidRatio = distance / euclidDist;

            var features = new string[]
            {
                isReachable.ToString(),
                distance.ToString(),
                nnConfWeight.ToString(),
                angleWeight.ToString(),
                euclidDist.ToString(),
                nnConfSqrDiff.ToString(),
                areBothRoadEnds.ToString(),
                avgColorDiff.ToString(),
                avgPathColor.ToString(),
                awd.ToString(),
                cwd.ToString(),
                distanceEuclidRatio.ToString(),
            };

            return string.Join(" ", features);
        }

